import * as fs from 'node:fs'
import * as path from 'node:path'
import * as prettier from 'prettier'

import { ColorPalette, DEFAULT_COLOR_PALETTE_INPUT } from './palette'

/** Not checked in; regenerated by `pnpm gen:theme`. */
const outputPath = path.resolve(import.meta.dirname, 'generated', 'style.css')

const palette = new ColorPalette(DEFAULT_COLOR_PALETTE_INPUT)

const css = palette.css({
    overrideTwColors: true,
    selector: '@theme',
})

const formatted = await prettier.format(css, {
    ...(await prettier.resolveConfig(outputPath)),
    parser: 'css',
})

fs.mkdirSync(path.dirname(outputPath), { recursive: true })
fs.writeFileSync(outputPath, formatted)
